import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { Song } from '../models/song.model';

@Injectable({
  providedIn: 'root'
})
export class MusicService {

  // ---- Mock catalog -------------------------------------------------
  // Cover art from a public placeholder service, audio from public-domain
  // demo tracks (SoundHelix) so the player is fully functional out of the box.
  private songs: Song[] = [
    {
      id: 1,
      title: 'Midnight Drive',
      artist: 'Nova Sound',
      album: 'City Lights',
      duration: '3:58',
      durationSec: 238,
      cover: 'https://picsum.photos/seed/midnightdrive/300/300',
      audioSrc: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3',
      genre: 'Electronic',
      isLiked: true
    },
    {
      id: 2,
      title: 'Golden Hour',
      artist: 'Aria Bloom',
      album: 'Sunset Diaries',
      duration: '4:12',
      durationSec: 252,
      cover: 'https://picsum.photos/seed/goldenhour/300/300',
      audioSrc: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3',
      genre: 'Pop',
      isLiked: false
    },
    {
      id: 3,
      title: 'Echoes of Rain',
      artist: 'Silent Grove',
      album: 'Wandering',
      duration: '5:03',
      durationSec: 303,
      cover: 'https://picsum.photos/seed/echoesofrain/300/300',
      audioSrc: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-3.mp3',
      genre: 'Ambient',
      isLiked: false
    },
    {
      id: 4,
      title: 'Neon Skyline',
      artist: 'Nova Sound',
      album: 'City Lights',
      duration: '3:34',
      durationSec: 214,
      cover: 'https://picsum.photos/seed/neonskyline/300/300',
      audioSrc: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-4.mp3',
      genre: 'Electronic',
      isLiked: true
    },
    {
      id: 5,
      title: 'Coastal Breeze',
      artist: 'Aria Bloom',
      album: 'Sunset Diaries',
      duration: '3:47',
      durationSec: 227,
      cover: 'https://picsum.photos/seed/coastalbreeze/300/300',
      audioSrc: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-5.mp3',
      genre: 'Pop',
      isLiked: false
    },
    {
      id: 6,
      title: 'Restless Streets',
      artist: 'Kevin Cole',
      album: 'Urban Tales',
      duration: '4:21',
      durationSec: 261,
      cover: 'https://picsum.photos/seed/restlessstreets/300/300',
      audioSrc: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-6.mp3',
      genre: 'Hip-Hop',
      isLiked: false
    },
    {
      id: 7,
      title: 'Fading Memories',
      artist: 'Silent Grove',
      album: 'Wandering',
      duration: '4:45',
      durationSec: 285,
      cover: 'https://picsum.photos/seed/fadingmemories/300/300',
      audioSrc: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-7.mp3',
      genre: 'Ambient',
      isLiked: true
    },
    {
      id: 8,
      title: 'Electric Pulse',
      artist: 'Kevin Cole',
      album: 'Urban Tales',
      duration: '3:29',
      durationSec: 209,
      cover: 'https://picsum.photos/seed/electricpulse/300/300',
      audioSrc: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-8.mp3',
      genre: 'Hip-Hop',
      isLiked: false
    }
  ];

  // ---- Playback state (shared across components via RxJS) -----------
  private currentSongSubject = new BehaviorSubject<Song | null>(null);
  private isPlayingSubject = new BehaviorSubject<boolean>(false);

  currentSong$: Observable<Song | null> = this.currentSongSubject.asObservable();
  isPlaying$: Observable<boolean> = this.isPlayingSubject.asObservable();

  getSongs(): Song[] {
    return this.songs;
  }

  getCurrentSong(): Song | null {
    return this.currentSongSubject.value;
  }

  playSong(song: Song): void {
    this.currentSongSubject.next(song);
    this.isPlayingSubject.next(true);
  }

  togglePlay(state?: boolean): void {
    this.isPlayingSubject.next(state ?? !this.isPlayingSubject.value);
  }

  playNext(): void {
    const current = this.currentSongSubject.value;
    if (!current) return;
    const idx = this.songs.findIndex(s => s.id === current.id);
    const nextIdx = (idx + 1) % this.songs.length;
    this.playSong(this.songs[nextIdx]);
  }

  playPrevious(): void {
    const current = this.currentSongSubject.value;
    if (!current) return;
    const idx = this.songs.findIndex(s => s.id === current.id);
    const prevIdx = (idx - 1 + this.songs.length) % this.songs.length;
    this.playSong(this.songs[prevIdx]);
  }

  toggleLike(song: Song): void {
    song.isLiked = !song.isLiked;
  }
}
